// "Experiments" slides: the sample-only random-target study, the OSTIA
// comparison, and the oracle ablations. All numbers come from
// experiments_data.js, generated by ../make_demo_data.py from results/*.jsonl.

import { DATA } from "./experiments_data.js";
import { ORACLES } from "./presets.js";

const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c]);
const title = (task) => ORACLES[task]?.title ?? task;
const fmt = (v) => (v === 1 ? "1.0" : v.toFixed(3).replace(/^0/, "0"));
const pct = (v) => `${Math.round(v * 100)}%`;
const pop = (on, i, step = 120) => (on ? ` class="pop" style="animation-delay:${i * step}ms"` : "");

const FAMILIES = [
  ["ia=3, oa=2, c<=2", "|Σ| = 3, |Γ| = 2, chunks ≤ 2"],
  ["ia=4, oa=2, c<=3", "|Σ| = 4, |Γ| = 2, chunks ≤ 3"],
  ["ia=5, oa=4, c<=4", "|Σ| = 5, |Γ| = 4, chunks ≤ 4"],
];
// Same colors as the paper's figure.
const SIZES = [["2x2", "2×2", "#2a78d6"], ["4x4", "4×4", "#eb6834"], ["6x6", "6×6", "#1baf7a"], ["10x10", "10×10", "#4a3aa7"]];
const NS = [50, 100, 200, 400];
const TASKS = DATA.battery.map((r) => r.task);
const SUBSEQUENTIAL = new Set(["local_cad_abcd", "insert_a_between_cd_abcd"]);

const point = (fam, size, n) => DATA.random.points.find((p) => p.family === fam && p.size === size && p.n === n);

// ---------------------------------------------------------------------------
// Charts
// ---------------------------------------------------------------------------

// One small line chart per family. metric "agreement" draws mean held-out
// agreement (solid) and exact recovery (dashed); "fallback" draws the share of
// test strings that hit an undefined state or entry. Sizes up to index `upto`.
function familyCharts({ metric, upto, anim, H = 230 }) {
  const W = 300, L = 46, R = 14, T = 30, B = 40;
  const x = (n) => L + (Math.log2(n / NS[0]) / Math.log2(NS.at(-1) / NS[0])) * (W - L - R);
  const y = (v) => T + (1 - v) * (H - T - B);
  return `<div class="charts">${FAMILIES.map(([fam, label]) => {
    let s = `<svg viewBox="0 0 ${W} ${H}" class="chart" role="img" aria-label="${esc(label)}">`;
    s += `<text x="${(L + W - R) / 2}" y="16" class="ctitle" text-anchor="middle">${esc(label)}</text>`;
    for (const v of [0, 0.25, 0.5, 0.75, 1]) {
      s += `<line x1="${L}" x2="${W - R}" y1="${y(v)}" y2="${y(v)}" class="grid"/>`;
      s += `<text x="${L - 6}" y="${y(v)}" class="tick" text-anchor="end" dominant-baseline="central">${v === 0 || v === 1 ? v : v.toFixed(2)}</text>`;
    }
    for (const n of NS) s += `<text x="${x(n)}" y="${H - B + 16}" class="tick" text-anchor="middle">${n}</text>`;
    s += `<text x="${(L + W - R) / 2}" y="${H - 6}" class="tick" text-anchor="middle">training examples</text>`;
    SIZES.forEach(([size, slabel, color], i) => {
      if (i > upto) return;
      const pts = NS.map((n) => point(fam, size, n)).filter(Boolean);
      const series = metric === "agreement" ? [["agreement", ""], ["exact", "6 4"]] : [["fallback", ""]];
      let g = "";
      for (const [key, dash] of series) {
        g += `<polyline points="${pts.map((p) => `${x(p.n)},${y(p[key])}`).join(" ")}" fill="none" stroke="${color}" stroke-width="${dash ? 1.8 : 2.6}" stroke-dasharray="${dash}"/>`;
        for (const p of pts) {
          const tip = metric === "agreement"
            ? `${slabel}, n = ${p.n}: agreement ${fmt(p.agreement)}, exact recovery ${p.exact * p.targets}/${p.targets}`
            : `${slabel}, n = ${p.n}: ${pct(p.fallback)} of test strings hit an undefined state or entry`;
          g += `<circle cx="${x(p.n)}" cy="${y(p[key])}" r="${dash ? 3 : 4}" fill="${dash ? "var(--panel)" : color}" stroke="${color}" stroke-width="1.6"><title>${tip}</title></circle>`;
        }
      }
      s += `<g${pop(anim && i === upto, 0)}>${g}</g>`;
    });
    return s + "</svg>";
  }).join("")}</div>`;
}

function sizeLegend(upto, metric) {
  return `<div class="clegend">${SIZES.map(([, label, color], i) =>
    `<span class="${i > upto ? "off" : ""}"><i style="background:${color}"></i>${label}</span>`).join("")}
    ${metric === "agreement" ? `<span><b class="lsolid"></b>held-out agreement</span><span><b class="ldash"></b>exact recovery</span>` : ""}</div>`;
}

// ---------------------------------------------------------------------------
// Ablation helpers
// ---------------------------------------------------------------------------

function smallRun(task, k) {
  const rows = DATA.smallSample.filter((r) => r.task === task && r.k === k);
  const done = rows.find((r) => r.q_left !== undefined);
  if (done) return done;
  // A timed-out run may have finished in the longer retry.
  const longer = DATA.smallSampleLong.find((r) => r.task === task && r.k === k);
  const timeouts = [...rows, ...(longer ? [longer] : [])].map((r) => r.timeout_seconds).filter(Boolean);
  if (longer && longer.q_left !== undefined) return { ...longer, slow: true };
  return { timeout: Math.max(0, ...timeouts) };
}

const duration = (s) => (s >= 120 ? `${Math.round(s / 60)} min` : `${Math.round(s)} s`);

function smallCell(r) {
  if (r.timeout !== undefined) return `<td class="tcell to">did not finish in ${duration(r.timeout)}</td>`;
  const v = r.strict_agreement ?? r.oracle_agreement;
  const cls = v === 1 ? "ok" : v >= 0.9 ? "mid" : "bad";
  const note = r.slow ? `<span class="muted"> · ${duration(r.learn_seconds)}</span>` : "";
  return `<td class="tcell ${cls}"><b>${fmt(v)}</b> <span class="muted">${r.q_left}/${r.q_right}</span>${note}</td>`;
}

// ---------------------------------------------------------------------------
// Slides
// ---------------------------------------------------------------------------

const SECTIONS = ["Without an oracle", "Random targets", "OSTIA", "Oracle ablation", "Wrap-up"];
const SLIDES = [];

SLIDES.push({
  section: 0,
  title: "Learning without an oracle",
  builds: 3,
  html: () => `
    <table class="map cmp">
      <thead><tr><th></th><th>With the oracle</th><th>Sample-only</th></tr></thead>
      <tbody>
        <tr data-b="0"><td><b>Merging</b></td><td>check the training data <b>and</b> witness queries</td><td>check the training data only</td></tr>
        <tr data-b="1"><td><b>Completion</b></td><td>query π(q)·a·σ(p) for every missing ω entry</td><td>fill an entry only if that string is in the sample</td></tr>
        <tr data-b="1"><td><b>Minimization</b></td><td>on a total table</td><td>on partial rows and columns (undefined is a value of its own)</td></tr>
        <tr data-b="1"><td><b>Result</b></td><td>a total bimachine</td><td>may be partial: some inputs hit an undefined state or entry</td></tr>
      </tbody>
    </table>
    <div class="takeaway" data-b="2">
      <p>How far does the data alone get? Two experiments:</p>
      <p>1. <b>Random target bimachines</b>, learned sample-only: how much data until the structure is recovered?</p>
      <p>2. The <b>benchmark battery with only 50 examples</b>: what does the oracle add?</p>
    </div>`,
});

SLIDES.push({
  section: 1,
  title: "Random target bimachines",
  builds: 2,
  html: () => `
    <div class="two even">
      <div>
        <h3>Targets</h3>
        <ul class="points small">
          <li>Random total left and right DFAs and a random total ω, normalized (minimized and renumbered); targets whose sides shrink are redrawn</li>
          <li>Three families:<div class="chips">${FAMILIES.map(([, l]) => `<span class="chip">${esc(l)}</span>`).join("")}</div></li>
          <li>Sizes ${SIZES.map(([, l]) => l).join(", ")}; five targets per point</li>
        </ul>
      </div>
      <div data-b="1">
        <h3>Training and evaluation</h3>
        <ul class="points small">
          <li><b>${NS.join(", ")}</b> distinct training strings of length ≤ 6</li>
          <li>Sample-only learner: <b>no oracle queries</b></li>
          <li><b>Held-out agreement:</b> exact chunk-sequence match on 700 unseen strings of length ≤ 10</li>
          <li><b>Exact recovery:</b> the learned bimachine is identical to the normalized target</li>
        </ul>
      </div>
    </div>`,
});

SLIDES.push({
  section: 1,
  title: "Agreement rises before exact recovery",
  builds: 5,
  html: () => `
    <div id="rt-legend"></div>
    <div id="rt-charts" class="fig"></div>
    <p class="caption" id="rt-cap"></p>`,
  update(root, b, animate) {
    const upto = Math.min(b, 3);
    root.querySelector("#rt-legend").innerHTML = sizeLegend(upto, "agreement");
    root.querySelector("#rt-charts").innerHTML = familyCharts({ metric: "agreement", upto, anim: animate && b <= 3 });
    const p = (f, s, n) => point(FAMILIES[f][0], s, n);
    const range = (s, n, key) => {
      const v = FAMILIES.map((_, f) => p(f, s, n)?.[key]).filter((x) => x !== undefined);
      const lo = Math.min(...v), hi = Math.max(...v);
      return lo === hi ? fmt(lo) : `${fmt(lo)}–${fmt(hi)}`;
    };
    const cap = [
      `2×2: exact recovery from as few as 50 examples (agreement ${range("2x2", 50, "agreement")} at n = 50).`,
      `4×4: agreement reaches ${range("4x4", 400, "agreement")} at n = 400, but exact recovery only ${range("4x4", 400, "exact")}.`,
      `6×6: agreement ${range("6x6", 400, "agreement")} at n = 400; exact recovery ${range("6x6", 400, "exact")}.`,
      `10×10: agreement goes from ${range("10x10", 50, "agreement")} at n = 50 to ${range("10x10", 400, "agreement")} at n = 400; never exact.`,
      "Data alone generalizes well before it pins down the exact structure, and bigger targets need much more data. Hover a point for its values.",
    ];
    root.querySelector("#rt-cap").textContent = cap[b];
  },
});

SLIDES.push({
  section: 1,
  title: "Why exact recovery lags",
  builds: 3,
  html: () => {
    const cov = DATA.random.coverage;
    const cell = (fam, size) => {
      const c = cov.find((r) => r.family === fam && r.size === size);
      if (!c) return "<td></td>";
      const lo = Math.min(...c.values), hi = Math.max(...c.values);
      const full = c.values.filter((v) => v >= 1).length;
      return `<td class="${lo < 1 ? "short" : ""}">${lo === hi ? pct(lo) : `${pct(lo)}–${pct(hi)}`}${lo < 1 ? ` <span class="muted">${full}/${c.values.length} fully covered</span>` : ""}</td>`;
    };
    return `
    <h3>1. Undefined lookups</h3>
    <p class="note">Share of test strings that reach an undefined state or ω entry. Such a string is always wrong, since the output alphabet is disjoint from the input alphabet.</p>
    <div id="fb-legend"></div>
    <div id="fb-charts" class="fig short"></div>
    <div data-b="1" class="covbox">
      <h3>2. A ceiling from short strings</h3>
      <p class="note">Share of each target's ω entries that <b>any</b> string of length ≤ 6 can reach (range over the five targets). Below 100%, no sample of such strings can recover the target exactly.</p>
      <table class="cov"><thead><tr><th></th>${SIZES.map(([, l]) => `<th>${l}</th>`).join("")}</tr></thead>
      <tbody>${FAMILIES.map(([fam, label]) => `<tr><th>${esc(label)}</th>${SIZES.map(([s]) => cell(fam, s)).join("")}</tr>`).join("")}</tbody></table>
    </div>
    <div class="takeaway" data-b="2">
      <p>Exact recovery needs <b>every</b> output entry. Short random strings visit some entries rarely or never, and without an oracle there is nothing else to ask.</p>
    </div>`;
  },
  update(root, b, animate) {
    root.querySelector("#fb-legend").innerHTML = sizeLegend(3, "fallback");
    root.querySelector("#fb-charts").innerHTML = familyCharts({ metric: "fallback", upto: 3, anim: animate && b === 0, H: 190 });
  },
});

SLIDES.push({
  section: 2,
  title: "Comparison with OSTIA",
  builds: 3,
  html: () => {
    const max = Math.log10(1000);
    const bar = (states, cls) => `<span class="sbar ${cls}" style="width:${(Math.log10(Math.max(states, 1)) / max) * 100}%"></span>`;
    const rows = TASKS.map((task) => {
      const ours = DATA.battery.find((r) => r.task === task);
      const ost = DATA.ostia.find((r) => r.task === task);
      const sub = SUBSEQUENTIAL.has(task);
      return `<tr class="${sub ? "sub" : ""}">
        <td>${esc(title(task))}${sub ? ` <span class="tag">subsequential</span>` : ""}</td>
        <td class="sbars"><div>${bar(ours.q_left + ours.q_right, "ours")}<span class="bnum">${ours.q_left} + ${ours.q_right}</span></div>
          <div data-b="1">${bar(ost.states, "ostia")}<span class="bnum">${ost.states}</span></div></td>
        <td class="acc"><div class="ok">${fmt(ours.oracle_agreement)}</div><div data-b="1" class="${ost.acc === 1 ? "ok" : "bad"}">${fmt(ost.acc)}</div></td>
      </tr>`;
    }).join("");
    const non = DATA.ostia.filter((r) => !SUBSEQUENTIAL.has(r.task));
    const lo = (k) => Math.min(...non.map((r) => r[k])), hi = (k) => Math.max(...non.map((r) => r[k]));
    return `
    <p class="note">The battery, with the paper's 2,000 training strings. States on a log scale: <span class="sw-ours"></span> our bimachine (|Q<sub>L</sub>| + |Q<sub>R</sub>|) <span data-b="1"><span class="sw-ostia"></span> OSTIA's subsequential transducer</span>. Right: agreement on 500 test strings.</p>
    <table class="ostia"><colgroup><col style="width:30%"><col style="width:56%"><col style="width:14%"></colgroup>${rows}</table>
    <div class="takeaway" data-b="2">
      <p>The two subsequential tasks are easy for OSTIA too. On the other eight, OSTIA's transducers fit the training data but have ${lo("states")}–${hi("states")} states and ${fmt(lo("acc"))}–${fmt(hi("acc"))} accuracy: these functions are outside its class.</p>
      <p class="note">Not a like-for-like comparison: OSTIA gets unaligned whole outputs and no oracle. It shows what the representation can express.</p>
    </div>`;
  },
});

SLIDES.push({
  section: 3,
  title: "How much does the oracle buy? 50 examples",
  builds: 5,
  html: () => {
    const rows = TASKS.map((task) => `<tr><td>${esc(title(task))}</td>${[null, 0, 80].map((k, j) => smallCell(smallRun(task, k)).replace("<td", `<td data-b="${j + 1}"`)).join("")}</tr>`).join("");
    const big = DATA.kSweep.filter((r) => r.k === 0 && r.q_left !== undefined);
    const at80 = TASKS.map((task) => [task, smallRun(task, 80)]);
    const perfect = at80.filter(([, r]) => r.oracle_agreement === 1);
    const backfire = at80.filter(([, r]) => r.oracle_agreement !== 1).map(([task, r]) => r.timeout !== undefined
      ? `<b>${esc(title(task))}</b>: did not finish in ${duration(r.timeout)}`
      : `<b>${esc(title(task))}</b>: ${fmt(r.oracle_agreement)} with ${r.q_left}/${r.q_right} states, after ${r.queries.toLocaleString("en-US")} queries and ${duration(r.learn_seconds)}`);
    const easy = big.filter((r) => r.oracle_agreement === 1).length;
    return `
    <p class="note">The battery with <b>50</b> training strings instead of 2,000. Each cell: agreement on 500 test strings (strict: an undefined lookup counts as wrong), then |Q<sub>L</sub>|/|Q<sub>R</sub>|.</p>
    <table class="small">
      <thead><tr><th>Task</th><th data-b="1">no oracle<br><span class="muted">sample-only</span></th><th data-b="2">k = 0<br><span class="muted">completion queries only</span></th><th data-b="3">k = 80<br><span class="muted">witnesses + completion</span></th></tr></thead>
      <tbody>${rows}</tbody>
    </table>
    <div class="takeaway" data-b="4">
      <p>With few examples, witness queries are what turn an overfit machine into the right one: ${perfect.length} of ${TASKS.length} tasks are perfect at k = 80, at a cost of up to ${Math.max(...perfect.map(([, r]) => r.queries))} queries.</p>
      ${backfire.length ? `<p>On the global tasks the witnesses backfire: ${backfire.join("; ")}.</p>` : ""}
      ${big.length === TASKS.length ? `<p>With the paper's 2,000 examples, ${easy} of ${TASKS.length} tasks are learned perfectly with <b>no</b> witness queries: the sample already contains almost every short string.</p>` : ""}
    </div>`;
  },
});

SLIDES.push({
  section: 3,
  title: "The witness budget k: global-or-local",
  builds: 2,
  html: () => {
    const task = "global_or_local_abcd";
    const ks = [...new Set(DATA.kSweep.map((r) => r.k))].sort((a, b) => a - b);
    const rows = ks.map((k) => DATA.kSweep.find((r) => r.task === task && r.k === k)).filter(Boolean);
    const others = TASKS.filter((t) => t !== task);
    const swept = others.filter((t) => DATA.kSweep.filter((r) => r.task === t).length === ks.length);
    const stable = swept.filter((t) => {
      const rs = DATA.kSweep.filter((r) => r.task === t);
      return rs.every((r) => r.oracle_agreement === 1 && r.q_left === rs[0].q_left && r.q_right === rs[0].q_right);
    }).length;
    const body = rows.map((r, i) => r.q_left === undefined
      ? `<tr${pop(false, i)}><td>${r.k}</td><td colspan="4" class="to">did not finish in ${duration(r.timeout_seconds)}</td></tr>`
      : `<tr><td>${r.k}</td><td>${r.q_left}/${r.q_right}</td><td class="${r.oracle_agreement === 1 ? "ok" : "bad"}">${fmt(r.oracle_agreement)}</td><td>${r.queries.toLocaleString("en-US")}</td><td>${duration(r.learn_seconds)}</td></tr>`).join("");
    return `
    <p class="note">2,000 training strings, as in the paper; k is the maximum number of witness strings per candidate merge (continuations or heads of length ≤ 3).</p>
    <table class="ksweep"><thead><tr><th>k</th><th>|Q<sub>L</sub>|/|Q<sub>R</sub>|</th><th>agreement</th><th>queries</th><th>time</th></tr></thead><tbody>${body}</tbody></table>
    ${rows.length < ks.length || !rows.length ? `<p class="note">Some runs are still missing from the results file.</p>` : ""}
    <div class="takeaway" data-b="1">
      <p>A <b>partial</b> witness set can be worse than none: enough to accept merges whose witness paths then grow the machine, not enough to rule out the wrong ones. Near-exhaustive witnesses (k = 80 covers all continuations up to length 3) reject wrong merges early.</p>
      <p class="note">${swept.length === others.length ? `The other ${others.length} tasks` : `${swept.length} of the other ${others.length} tasks (the rest are not in the results yet)`}: ${stable === swept.length ? "all" : stable} learn the same machine with perfect agreement for every k. Preliminary; not in the paper.</p>
    </div>`;
  },
});

SLIDES.push({
  section: 4,
  title: "Takeaways",
  builds: 4,
  html: () => `
    <ul class="points">
      <li data-b="0"><b>Direct bimachine learning works.</b> With aligned data and a chunk oracle, the learner recovers compact bimachines with perfect agreement on all ten benchmark tasks, eight of which no subsequential transducer can express.</li>
      <li data-b="1"><b>Data alone generalizes</b>, but exact structure needs more data, and some entries are out of reach of short samples.</li>
      <li data-b="2"><b>The oracle buys exactness</b> when data is scarce, at a cost in queries, and with care about the witness budget.</li>
      <li data-b="3"><b>Next:</b> learning from <b>unaligned</b> input–output pairs, and distilling neural sequence models into bimachines.</li>
    </ul>`,
});

export { SLIDES as EXP_SLIDES, SECTIONS as EXP_SECTIONS };
